package main

import (
	"crypto/ecdsa"
	"crypto/elliptic"
	"crypto/rand"
	"crypto/tls"
	"crypto/x509"
	"crypto/x509/pkix"
	"encoding/pem"
	"errors"
	"fmt"
	"math/big"
	"net"
	"os"
	"path/filepath"
	"runtime"
	"time"
)

const (
	certFileName = "tls.cert"
	keyFileName  = "tls.key"
	// certValidity matches LND's autogenerated certificate (14 months).
	certValidity = 14 * 30 * 24 * time.Hour
	certOrg      = "nltg-lnd-rest autogenerated cert"
)

// listenerTLS returns the REST listener's TLS configuration and the path of
// the certificate clients should trust. HTTP/2 is not offered: LND's REST
// listener speaks HTTP/1.1 and the WebSocket upgrade needs it.
func listenerTLS(c Config, logf func(string, ...any)) (*tls.Config, string, error) {
	certPath, keyPath := c.RestTLSCert, c.RestTLSKey
	if certPath == "" {
		certPath, keyPath = filepath.Join(c.TLSDir, certFileName), filepath.Join(c.TLSDir, keyFileName)
		created, err := ensureSelfSignedCert(c.TLSDir, listenHostIP(c.Listen), c.TLSExtraIPs, c.TLSExtraDomains, time.Now())
		if err != nil {
			return nil, "", err
		}
		if created {
			logf("generated a self-signed TLS certificate at %s", certPath)
		}
	}
	if err := checkKeyPermissions(keyPath); err != nil {
		return nil, "", err
	}
	pair, err := tls.LoadX509KeyPair(certPath, keyPath)
	if err != nil {
		return nil, "", fmt.Errorf("load listener TLS certificate: %w", err)
	}
	return &tls.Config{
		Certificates: []tls.Certificate{pair},
		MinVersion:   tls.VersionTLS12,
		NextProtos:   []string{"http/1.1"},
	}, certPath, nil
}

// checkKeyPermissions refuses a private key readable by group or others.
func checkKeyPermissions(keyPath string) error {
	if runtime.GOOS == "windows" {
		return nil
	}
	info, err := os.Stat(keyPath)
	if err != nil {
		return fmt.Errorf("listener TLS key: %w", err)
	}
	if info.Mode().Perm()&0o077 != 0 {
		return fmt.Errorf("listener TLS key %s is accessible by group or others (mode %o): chmod 600 it", keyPath, info.Mode().Perm())
	}
	return nil
}

// ensureSelfSignedCert creates dir/tls.cert and dir/tls.key unless a valid
// pair is there. An expired or unreadable generated certificate is replaced.
func ensureSelfSignedCert(dir string, listenIP net.IP, extraIPs, extraDomains []string, now time.Time) (bool, error) {
	certPath, keyPath := filepath.Join(dir, certFileName), filepath.Join(dir, keyFileName)
	if certPEM, err := os.ReadFile(certPath); err == nil {
		if _, kerr := os.Stat(keyPath); kerr == nil {
			if cert, perr := parseCertPEM(certPEM); perr == nil && now.Before(cert.NotAfter) {
				return false, nil
			}
		}
	} else if !errors.Is(err, os.ErrNotExist) {
		return false, fmt.Errorf("read %s: %w", certPath, err)
	}
	if err := os.MkdirAll(dir, 0o700); err != nil {
		return false, fmt.Errorf("create --tls-dir: %w", err)
	}
	certPEM, keyPEM, err := generateCert(listenIP, extraIPs, extraDomains, now)
	if err != nil {
		return false, err
	}
	// The key goes first so a certificate is never left without its key.
	if err := writeFileAtomic(keyPath, keyPEM, 0o600); err != nil {
		return false, err
	}
	if err := writeFileAtomic(certPath, certPEM, 0o644); err != nil {
		return false, err
	}
	return true, nil
}

func parseCertPEM(data []byte) (*x509.Certificate, error) {
	block, _ := pem.Decode(data)
	if block == nil || block.Type != "CERTIFICATE" {
		return nil, errors.New("no PEM certificate")
	}
	return x509.ParseCertificate(block.Bytes)
}

func generateCert(listenIP net.IP, extraIPs, extraDomains []string, now time.Time) ([]byte, []byte, error) {
	key, err := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
	if err != nil {
		return nil, nil, err
	}
	serial, err := rand.Int(rand.Reader, new(big.Int).Lsh(big.NewInt(1), 128))
	if err != nil {
		return nil, nil, err
	}
	host, _ := os.Hostname()
	if host == "" {
		host = "localhost"
	}
	dnsNames := []string{"localhost"}
	if host != "localhost" {
		dnsNames = append(dnsNames, host)
	}
	dnsNames = append(dnsNames, extraDomains...)
	ips := []net.IP{net.IPv4(127, 0, 0, 1), net.IPv6loopback}
	if listenIP != nil && !listenIP.IsUnspecified() && !listenIP.IsLoopback() {
		ips = append(ips, listenIP)
	}
	for _, s := range extraIPs {
		if ip := net.ParseIP(s); ip != nil {
			ips = append(ips, ip)
		}
	}
	template := x509.Certificate{
		SerialNumber:          serial,
		Subject:               pkix.Name{Organization: []string{certOrg}, CommonName: host},
		NotBefore:             now.Add(-time.Hour),
		NotAfter:              now.Add(certValidity),
		KeyUsage:              x509.KeyUsageKeyEncipherment | x509.KeyUsageDigitalSignature | x509.KeyUsageCertSign,
		ExtKeyUsage:           []x509.ExtKeyUsage{x509.ExtKeyUsageServerAuth},
		IsCA:                  true,
		BasicConstraintsValid: true,
		DNSNames:              dnsNames,
		IPAddresses:           ips,
	}
	der, err := x509.CreateCertificate(rand.Reader, &template, &template, &key.PublicKey, key)
	if err != nil {
		return nil, nil, fmt.Errorf("create certificate: %w", err)
	}
	keyDER, err := x509.MarshalECPrivateKey(key)
	if err != nil {
		return nil, nil, err
	}
	return pem.EncodeToMemory(&pem.Block{Type: "CERTIFICATE", Bytes: der}),
		pem.EncodeToMemory(&pem.Block{Type: "EC PRIVATE KEY", Bytes: keyDER}), nil
}

// writeFileAtomic writes through a temporary file created with the final
// mode, then renames it into place.
func writeFileAtomic(path string, data []byte, mode os.FileMode) error {
	tmp, err := os.CreateTemp(filepath.Dir(path), "."+filepath.Base(path)+".tmp-*")
	if err != nil {
		return err
	}
	name := tmp.Name()
	defer os.Remove(name)
	if err := tmp.Chmod(mode); err != nil {
		tmp.Close()
		return err
	}
	if _, err := tmp.Write(data); err != nil {
		tmp.Close()
		return err
	}
	if err := tmp.Sync(); err != nil {
		tmp.Close()
		return err
	}
	if err := tmp.Close(); err != nil {
		return err
	}
	return os.Rename(name, path)
}

// listenHostIP returns the listen address's IP, or nil for a name.
func listenHostIP(listen string) net.IP {
	host, _, err := net.SplitHostPort(listen)
	if err != nil {
		return nil
	}
	return net.ParseIP(host)
}
